incidents.resolution_patch:
--- a/services/payment-service/src/main/java/com/swagstore/payment/PaymentService.java
+++ b/services/payment-service/src/main/java/com/swagstore/payment/PaymentService.java
@@ charge @@
-while (result == null && attempts++ < 5) {
-  result = stripe.charges().create(params); // no backoff
-}
+long backoffMs = 250;
+while (result == null && attempts++ < 5) {
+  try {
+    result = stripe.charges().create(params);
+  } catch (StripeRateLimitException e) {
+    Thread.sleep(backoffMs);
+    backoffMs = Math.min(backoffMs * 2, 4000);
+  }
+}

