incidents.resolution_patch:
--- a/services/payment-service/src/main/java/com/swagstore/payment/PaymentWebhookHandler.java
+++ b/services/payment-service/src/main/java/com/swagstore/payment/PaymentWebhookHandler.java
@@ handle @@
-@PostMapping("/stripe/webhook")
-public ResponseEntity<?> handle(@RequestBody Event e) {
-  processor.process(e);
-  return ok();
-}
+@PostMapping("/stripe/webhook")
+public ResponseEntity<?> handle(@RequestBody Event e) {
+  try {
+    webhookQueue.enqueueDurable(e); // persists to DLQ-backed queue before ack
+  } catch (QueueUnavailableException qe) {
+    return ResponseEntity.status(503).build(); // let Stripe retry
+  }
+  return ok();
+}

